#include <iostream>
#include <string>
#include "../include/indicators.hpp"

int main(int argc, char* argv[]) {
    indicators::ProgressBar bar;
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    std::cout << bar.str() << std::endl;

    indicators::Percentage pct(0.75f);
    std::cout << pct.str() << std::endl;
    return 0;
}


/*
==============================
 TEST CASE EXAMPLES (Top 5)
==============================
--- Example 1 ---
Input Args: {"progress": "0", "total": "100", "width": "30", "percentage": "0.0"}
Program Output: [======================>       ] 75.0%
75.0%

--- Example 2 ---
Input Args: {"progress": "50", "total": "100", "width": "50", "percentage": "0.5"}
Program Output: [======================>       ] 75.0%
