 1	//! `indicators::Percentage`.
 2	
 3	use super::cxx_fmt;
 4	
 5	/// Formats a 0.0–1.0 fraction as a percentage with one decimal, e.g. `75.0%`.
 6	#[derive(Clone, Copy, Debug, PartialEq)]
 7	pub struct Percentage {
 8	    value: f32,
 9	}
10	
11	impl Percentage {
12	    pub fn new(value: f32) -> Self {
13	        Percentage { value }
14	    }
15	
16	    pub fn set_value(&mut self, value: f32) {
17	        self.value = value;
18	    }
19	
20	    pub fn value(&self) -> f32 {
21	        self.value
22	    }
23	
24	    /// Renders the percentage. Mirrors the C++ `str()` member: the `float` is
25	    /// widened to `double` before the multiply, then printed with
26	    /// `std::fixed` and a precision of one.
27	    pub fn str(&self) -> String {
28	        let mut s = cxx_fmt::fixed(self.value as f64 * 100.0, 1);
29	        s.push('%');
30	        s
31	    }
32	}
33	
34	impl std::fmt::Display for Percentage {
35	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
36	        f.write_str(&self.str())
37	    }
38	}
39	
40	#[cfg(test)]
41	mod tests {
42	    use super::*;
43	
44	    #[test]
45	    fn matches_the_cpp_test_program() {
46	        assert_eq!(Percentage::new(0.75).str(), "75.0%");
47	    }
48	
49	    #[test]
50	    fn common_fractions() {
51	        assert_eq!(Percentage::new(0.0).str(), "0.0%");
52	        assert_eq!(Percentage::new(1.0).str(), "100.0%");
53	        assert_eq!(Percentage::new(0.5).str(), "50.0%");
54	        assert_eq!(Percentage::new(0.125).str(), "12.5%");
55	    }
