cat > /tmp/probe.rs <<'EOF'
fn fixed1(x: f64) -> String { format!("{:.1}", x) }
fn main() {
    // Probe: does widening-then-multiply ever differ from float multiply,
    // as printed with fixed precision 1, over a dense sweep of 0..=1 floats?
    let mut diffs = 0u64; let mut examples = Vec::new();
    let mut bits: u32 = 0;
    // sweep all f32 in [0,1] would be huge; sample by stepping bit patterns
    while bits < 0x3f80_0001u32 {
        let v = f32::from_bits(bits);
        let a = fixed1(v as f64 * 100.0);
        let b = fixed1((v * 100.0f32) as f64);
        if a != b { diffs += 1; if examples.len() < 5 { examples.push((v, a, b)); } }
        bits = bits.wrapping_add(0x2000); // sample every 8192th pattern
    }
    println!("differing samples: {}", diffs);
    for (v,a,b) in examples { println!("  v={:e} f64-mul={} f32-mul={}", v, a, b); }
}
EOF
rustc -O -o /tmp/probe /tmp/probe.rs 2>&1 | tail -3; /tmp/probe

